mapper.select:
SELECT nr.*,yur.name as dname, (SELECT COUNT(*) FROM new_medical_examination_records nme WHERE nme.user_code = nr.user_code) AS numberPhysicalExaminations, t2.evaluationTime, assess.qtime, nepi.occupational_health_examination1 as v1, nepi.occupational_health_examination2 as v2, nepi.occupational_health_examination3 as v3, nepi.occupational_health_examination4 as v4, CASE WHEN assess.df_names IS NOT NULL AND assess.df_names != '' THEN '是' ELSE '否' END AS df_names, CASE WHEN assess.sk_names IS NOT NULL AND assess.sk_names != '' THEN '是' ELSE '否' END AS sk_names FROM new_reg nr LEFT JOIN new_employee_personal_information_card as nepi on nr.id=nepi.reg_id
LEFT JOIN ( SELECT user_code, MAX(time) AS evaluationTime FROM new_medical_examination_records GROUP BY user_code ) t2 ON nr.user_code = t2.user_code
LEFT JOIN `yh_user_make_card` AS c ON nr.user_code = c.User_Code left join yh_user_reginfo as yur on nr.responsible_health_manager_code=yur.user_code LEFT JOIN yh_user_admin_info AS ai ON c.doctor = ai.id LEFT JOIN ( SELECT user_code, qtime, df_names, sk_names FROM yh_disease_assess_total_report2 WHERE (user_code, qtime) IN ( SELECT user_code, MAX(qtime) FROM yh_disease_assess_total_report2 GROUP BY user_code ) ) assess ON nr.user_code = assess.user_code
(ai.user_code = #{doctor} or 1=1)
and nr.sex=#{sex}
and nr.name LIKE CONCAT('%', #{name}, '%')
and nr.work_unit LIKE CONCAT('%', #{workUnit}, '%')
and nr.department LIKE CONCAT('%', #{department}, '%')
and nr.phone LIKE CONCAT('%', #{phone}, '%')
and nr.responsible_health_manager_code=#{responsibleHealthManagerCode}
and nr.birth >= #{beginTime}
and nr.birth <= #{endTime}
LIMIT #{begin}, #{limit};

